package com.shatteredpixel.shatteredpixeldungeon.apd.difficulty;
import com.shatteredpixel.shatteredpixeldungeon.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.blobs.*;
import com.shatteredpixel.shatteredpixeldungeon.actors.buffs.*;
import com.shatteredpixel.shatteredpixeldungeon.plants.*;
import com.shatteredpixel.shatteredpixeldungeon.scenes.GameScene;
import com.watabou.noosa.Group;
import com.watabou.utils.*;
import org.junit.*;
import java.nio.file.*;
import static org.junit.Assert.*;
public class PlantDamageProvenanceTest {
 static final int CELL=312;
 SpecialBombDamageProvenanceTest fixture=new SpecialBombDamageProvenanceTest();java.util.Set<Actor> before;
 @Before public void setup()throws Exception{fixture.setup();before=Actor.all();Dungeon.level.plants=new SparseArray<>();Dungeon.level.blobs=new java.util.HashMap<>();java.lang.reflect.Field sf=GameScene.class.getDeclaredField("scene");sf.setAccessible(true);Object scene=sf.get(null);for(String n:new String[]{"gases","effects"}){java.lang.reflect.Field f=GameScene.class.getDeclaredField(n);f.setAccessible(true);f.set(scene,new Group());}}
 @After public void cleanup()throws Exception{for(Actor a:Actor.all())if(!before.contains(a))Actor.remove(a);fixture.cleanup();assertEquals(OffensiveDamageOrigin.UNATTRIBUTED,OffensiveEffectContext.current());}
 void rules(OffensiveDamageOrigin role,int pct){fixture.rules(role==OffensiveDamageOrigin.PLAYER?pct:100,role==OffensiveDamageOrigin.ENEMY?pct:100,role==OffensiveDamageOrigin.BOSS?pct:100);}
 Fire fire(){Fire f=(Fire)Dungeon.level.blobs.get(Fire.class);assertNotNull(f);return f;}
 ToxicGas gas(){ToxicGas g=(ToxicGas)Dungeon.level.blobs.get(ToxicGas.class);assertNotNull(g);return g;}
 int burn(Fire field)throws Exception{SpecialBombDamageProvenanceTest.Target t=new SpecialBombDamageProvenanceTest.Target(false);Actor.add(t);try{field.act();Burning b=t.buff(Burning.class);assertNotNull(b);Bundle state=new Bundle();b.storeInBundle(state);state.put("next_dmg",4);b.restoreFromBundle(state);b.act();assertEquals(1,t.hits.size());assertSame(b,t.sources.get(0));return t.hits.get(0);}finally{Actor.remove(t);}}
 Plant made(Plant.Seed seed,OffensiveDamageOrigin role){return seed.couchAttributed(CELL,null,role);}
 @Test public void firebloomUsesEveryCreatorAndDamagePercentageExactlyOnce()throws Exception{for(OffensiveDamageOrigin role:new OffensiveDamageOrigin[]{OffensiveDamageOrigin.PLAYER,OffensiveDamageOrigin.ENEMY,OffensiveDamageOrigin.BOSS})for(int pct=25;pct<=500;pct+=25){rules(role,pct);Plant p=made(new Firebloom.Seed(),role);p.activate(null);assertEquals(Math.round(4*pct/100f),burn(fire()));fire().fullyClear();}}
 @Test public void sorrowmossPoisonUsesEveryCreatorAndOriginalDuration()throws Exception{for(OffensiveDamageOrigin role:new OffensiveDamageOrigin[]{OffensiveDamageOrigin.PLAYER,OffensiveDamageOrigin.ENEMY,OffensiveDamageOrigin.BOSS})for(int pct=25;pct<=500;pct+=25){rules(role,pct);SpecialBombDamageProvenanceTest.Target t=new SpecialBombDamageProvenanceTest.Target(false);Actor.add(t);try{made(new Sorrowmoss.Seed(),role).activate(t);Poison poison=t.buff(Poison.class);assertNotNull(poison);Bundle state=new Bundle();poison.storeInBundle(state);int raw=DurationDamageProvenance.raw(state.getFloat("left"));poison.act();assertEquals(1,t.hits.size());assertEquals(Math.round(raw*pct/100f),(int)t.hits.get(0));assertSame(poison,t.sources.get(0));}finally{Actor.remove(t);}}}
 @Test public void rotberryGasUsesEveryCreatorWhileNaturalGasStaysEnvironmental()throws Exception{for(OffensiveDamageOrigin role:new OffensiveDamageOrigin[]{OffensiveDamageOrigin.PLAYER,OffensiveDamageOrigin.ENEMY,OffensiveDamageOrigin.BOSS})for(int pct=25;pct<=500;pct+=25){rules(role,pct);Plant p=made(new Rotberry.Seed(),role);p.activate(null);SpecialBombDamageProvenanceTest.Target t=new SpecialBombDamageProvenanceTest.Target(false);Actor.add(t);try{gas().act();assertEquals(1,t.hits.size());assertEquals(Math.round((1+Dungeon.scalingDepth()/5)*pct/100f),(int)t.hits.get(0));assertSame(gas(),t.sources.get(0));}finally{Actor.remove(t);gas().fullyClear();}}fixture.rules(500,500,500);Rotberry natural=new Rotberry();natural.pos=CELL;natural.activate(null);SpecialBombDamageProvenanceTest.Target u=new SpecialBombDamageProvenanceTest.Target(false);Actor.add(u);try{gas().act();assertEquals(1+Dungeon.scalingDepth()/5,(int)u.hits.get(0));}finally{Actor.remove(u);}}
 @Test public void plantSaveKeepsCreatorAndLegacySaveRemainsUnknown()throws Exception{fixture.rules(500,500,500);Plant original=made(new Firebloom.Seed(),OffensiveDamageOrigin.BOSS);Bundle saved=new Bundle();original.storeInBundle(saved);Firebloom restored=new Firebloom();restored.restoreFromBundle(saved);restored.activate(null);assertEquals(20,burn(fire()));fire().fullyClear();saved.remove("apd_plant_origin");Firebloom legacy=new Firebloom();legacy.restoreFromBundle(saved);legacy.activate(null);assertEquals(4,burn(fire()));}
 @Test public void neutralPlantTrackingPreservesFieldsDurationsAndNextRng()throws Exception{fixture.rules(100,100,100);Random.pushGenerator(913);int[] taggedDensity;int taggedVolume;long taggedNext;try{made(new Firebloom.Seed(),OffensiveDamageOrigin.PLAYER).activate(null);taggedDensity=fire().cur.clone();taggedVolume=fire().volume;taggedNext=Random.Long();fire().fullyClear();}finally{Random.popGenerator();}Dungeon.level.blobs=new java.util.HashMap<>();Random.pushGenerator(913);try{Firebloom natural=new Firebloom();natural.pos=CELL;natural.activate(null);assertArrayEquals(taggedDensity,fire().cur);assertEquals(taggedVolume,fire().volume);assertEquals(taggedNext,Random.Long());}finally{Random.popGenerator();}}
 @Test public void allPlayerAndTriggeredPlantCallersCaptureTheirActualSource()throws Exception{Path root=Paths.get(System.getProperty("apd.game.src"));String plant=Files.readString(root.resolve("plants/Plant.java")),level=Files.readString(root.resolve("levels/Level.java")),wand=Files.readString(root.resolve("items/wands/WandOfRegrowth.java")),cursed=Files.readString(root.resolve("items/wands/CursedWand.java")),bomb=Files.readString(root.resolve("items/bombs/RegrowthBomb.java")),sandals=Files.readString(root.resolve("items/artifacts/SandalsOfNature.java")),overgrowth=Files.readString(root.resolve("items/armor/curses/Overgrowth.java"));assertTrue(plant.contains("plantAttributed( this, cell, apdThrownOrigin() )"));assertTrue(plant.contains("apdThrowAttributed(hero.pos"));assertTrue(level.contains("Plant plantAttributed("));assertTrue(wand.contains("OffensiveDamageOrigin.capture(owner, null)"));assertTrue(cursed.contains("OffensiveDamageOrigin.capture(user, null)"));assertTrue(bomb.contains("plantPos, apdExplosionOrigin())"));assertTrue(sandals.contains("OffensiveDamageOrigin.capture(curUser, null)"));assertTrue(overgrowth.contains("OffensiveDamageOrigin.capture(attacker, null)"));}}
